import React, { useState, useEffect } from 'react';
import { shoppingAPI } from '../utils/api';

interface ShoppingList {
  id: number;
  title: string;
  status: string;
  auto_generated: boolean;
  sent_via_email: boolean;
  created_at: string;
}

const ShoppingPage: React.FC = () => {
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [selectedList, setSelectedList] = useState<ShoppingList | null>(null);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [newList, setNewList] = useState({
    title: '',
    items: [{ item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
  });

  useEffect(() => {
    loadShoppingLists();
  }, []);

  const loadShoppingLists = async () => {
    try {
      const response = await shoppingAPI.getAll();
      setLists(response.data);
    } catch (error) {
      console.error('Error loading shopping lists:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateFromInventory = async () => {
    try {
      await shoppingAPI.generateFromInventory();
      loadShoppingLists();
      alert('Düşük stoklu ürünlerden alışveriş listesi oluşturuldu!');
    } catch (error) {
      console.error('Error generating list:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await shoppingAPI.create(newList);
      setNewList({
        title: '',
        items: [{ item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
      });
      setShowForm(false);
      loadShoppingLists();
    } catch (error) {
      console.error('Error creating shopping list:', error);
    }
  };

  const addItem = () => {
    setNewList({
      ...newList,
      items: [...newList.items, { item_name: '', quantity: 1, unit: 'adet', estimated_cost: 0 }]
    });
  };

  const removeItem = (index: number) => {
    const updatedItems = newList.items.filter((_, i) => i !== index);
    setNewList({ ...newList, items: updatedItems });
  };

  const updateItem = (index: number, field: string, value: any) => {
    const updatedItems = newList.items.map((item, i) => 
      i === index ? { ...item, [field]: value } : item
    );
    setNewList({ ...newList, items: updatedItems });
  };

  const sendByEmail = async (listId: number) => {
    const emails = prompt('E-posta adreslerini virgülle ayırarak girin:');
    if (emails) {
      try {
        await shoppingAPI.sendByEmail(listId, emails.split(',').map(e => e.trim()));
        alert('Alışveriş listesi e-posta ile gönderildi!');
        loadShoppingLists();
      } catch (error) {
        console.error('Error sending email:', error);
      }
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'draft': return '#6c757d';
      case 'sent': return '#007bff';
      case 'completed': return '#28a745';
      default: return '#6c757d';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'draft': return 'Taslak';
      case 'sent': return 'Gönderildi';
      case 'completed': return 'Tamamlandı';
      default: return status;
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Alışveriş Listeleri</h1>
        <div style={styles.headerActions}>
          <button 
            style={styles.generateButton}
            onClick={generateFromInventory}
          >
            📦 Stoktan Oluştur
          </button>
          <button 
            style={styles.addButton}
            onClick={() => setShowForm(!showForm)}
          >
            {showForm ? 'İptal' : '+ Yeni Liste'}
          </button>
        </div>
      </header>

      {/* New List Form */}
      {showForm && (
        <div style={styles.formCard}>
          <h2 style={styles.formTitle}>Yeni Alışveriş Listesi</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <div style={styles.formGroup}>
              <label style={styles.label}>Liste Adı</label>
              <input
                type="text"
                style={styles.input}
                value={newList.title}
                onChange={(e) => setNewList({...newList, title: e.target.value})}
                placeholder="Örn: Haftalık Alışveriş"
                required
              />
            </div>

            <div style={styles.itemsSection}>
              <div style={styles.itemsHeader}>
                <h3 style={styles.itemsTitle}>Ürünler</h3>
                <button type="button" style={styles.addItemButton} onClick={addItem}>
                  + Ürün Ekle
                </button>
              </div>

              {newList.items.map((item, index) => (
                <div key={index} style={styles.itemRow}>
                  <input
                    type="text"
                    style={styles.itemInput}
                    placeholder="Ürün adı"
                    value={item.item_name}
                    onChange={(e) => updateItem(index, 'item_name', e.target.value)}
                    required
                  />
                  <input
                    type="number"
                    style={styles.quantityInput}
                    placeholder="Miktar"
                    value={item.quantity}
                    onChange={(e) => updateItem(index, 'quantity', Number(e.target.value))}
                    min="0.1"
                    step="0.1"
                    required
                  />
                  <select
                    style={styles.unitSelect}
                    value={item.unit}
                    onChange={(e) => updateItem(index, 'unit', e.target.value)}
                  >
                    <option value="adet">Adet</option>
                    <option value="kg">Kg</option>
                    <option value="lt">Litre</option>
                    <option value="paket">Paket</option>
                    <option value="kutu">Kutu</option>
                  </select>
                  <input
                    type="number"
                    style={styles.priceInput}
                    placeholder="Tahmini fiyat"
                    value={item.estimated_cost}
                    onChange={(e) => updateItem(index, 'estimated_cost', Number(e.target.value))}
                    min="0"
                    step="0.01"
                  />
                  {newList.items.length > 1 && (
                    <button
                      type="button"
                      style={styles.removeButton}
                      onClick={() => removeItem(index)}
                    >
                      ×
                    </button>
                  )}
                </div>
              ))}
            </div>

            <button type="submit" style={styles.submitButton}>
              Liste Oluştur
            </button>
          </form>
        </div>
      )}

      {/* Shopping Lists */}
      <div style={styles.listsGrid}>
        {loading ? (
          <div style={styles.loading}>Yükleniyor...</div>
        ) : lists.length === 0 ? (
          <div style={styles.emptyState}>
            <p>Henüz alışveriş listesi yok</p>
            <p>Yeni liste oluşturun veya stoktan otomatik oluşturun</p>
          </div>
        ) : (
          lists.map(list => (
            <div key={list.id} style={styles.listCard}>
              <div style={styles.listHeader}>
                <h3 style={styles.listTitle}>{list.title}</h3>
                <div style={styles.listBadges}>
                  {list.auto_generated && (
                    <span style={styles.autoBadge}>Otomatik</span>
                  )}
                  <span 
                    style={{
                      ...styles.statusBadge,
                      backgroundColor: getStatusColor(list.status)
                    }}
                  >
                    {getStatusText(list.status)}
                  </span>
                </div>
              </div>

              <div style={styles.listMeta}>
                <span style={styles.listDate}>
                  {new Date(list.created_at).toLocaleDateString('tr-TR')}
                </span>
                {list.sent_via_email && (
                  <span style={styles.emailSent}>📧 E-posta gönderildi</span>
                )}
              </div>

              <div style={styles.listActions}>
                <button 
                  style={styles.viewButton}
                  onClick={() => setSelectedList(list)}
                >
                  👁️ Görüntüle
                </button>
                {!list.sent_via_email && (
                  <button 
                    style={styles.emailButton}
                    onClick={() => sendByEmail(list.id)}
                  >
                    📧 E-posta Gönder
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* List Detail Modal */}
      {selectedList && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>{selectedList.title}</h2>
              <button 
                style={styles.closeButton}
                onClick={() => setSelectedList(null)}
              >
                ×
              </button>
            </div>
            <div style={styles.modalBody}>
              <p>Liste detayları burada gösterilecek...</p>
              <p>Bu özellik yakında tamamlanacak.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '24px',
  },
  title: {
    fontSize: '28px',
    fontWeight: '700',
    color: '#2c3e50',
    margin: 0,
  },
  headerActions: {
    display: 'flex',
    gap: '12px',
  },
  generateButton: {
    backgroundColor: '#17a2b8',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    padding: '12px 16px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
  addButton: {
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    padding: '12px 20px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
  formCard: {
    backgroundColor: '#fff',
    borderRadius: '12px',
    padding: '24px',
    marginBottom: '24px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    border: '1px solid #e9ecef',
  },
  formTitle: {
    fontSize: '20px',
    fontWeight: '600',
    color: '#2c3e50',
    marginBottom: '20px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '20px',
  },
  formGroup: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '4px',
  },
  label: {
    fontSize: '14px',
    fontWeight: '600',
    color: '#495057',
  },
  input: {
    padding: '10px 12px',
    border: '1px solid #ced4da',
    borderRadius: '6px',
    fontSize: '14px',
  },
  itemsSection: {
    border: '1px solid #e9ecef',
    borderRadius: '8px',
    padding: '16px',
  },
  itemsHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px',
  },
  itemsTitle: {
    fontSize: '16px',
    fontWeight: '600',
    color: '#2c3e50',
    margin: 0,
  },
  addItemButton: {
    backgroundColor: '#28a745',
    color: '#fff',
    border: 'none',
    borderRadius: '6px',
    padding: '8px 12px',
    fontSize: '12px',
    cursor: 'pointer',
  },
  itemRow: {
    display: 'grid',
    gridTemplateColumns: '2fr 80px 80px 100px 30px',
    gap: '8px',
    alignItems: 'center',
    marginBottom: '8px',
  },
  itemInput: {
    padding: '8px 10px',
    border: '1px solid #ced4da',
    borderRadius: '4px',
    fontSize: '14px',
  },
  quantityInput: {
    padding: '8px 10px',
    border: '1px solid #ced4da',
    borderRadius: '4px',
    fontSize: '14px',
  },
  unitSelect: {
    padding: '8px 10px',
    border: '1px solid #ced4da',
    borderRadius: '4px',
    fontSize: '14px',
    backgroundColor: '#fff',
  },
  priceInput: {
    padding: '8px 10px',
    border: '1px solid #ced4da',
    borderRadius: '4px',
    fontSize: '14px',
  },
  removeButton: {
    backgroundColor: '#dc3545',
    color: '#fff',
    border: 'none',
    borderRadius: '4px',
    width: '24px',
    height: '24px',
    cursor: 'pointer',
    fontSize: '16px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  submitButton: {
    backgroundColor: '#28a745',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    padding: '12px 24px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    alignSelf: 'flex-start',
  },
  listsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
    gap: '20px',
  },
  loading: {
    gridColumn: '1 / -1',
    textAlign: 'center' as const,
    padding: '40px',
    color: '#6c757d',
  },
  emptyState: {
    gridColumn: '1 / -1',
    textAlign: 'center' as const,
    padding: '60px 20px',
    color: '#95a5a6',
  },
  listCard: {
    backgroundColor: '#fff',
    borderRadius: '12px',
    padding: '20px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
    border: '1px solid #e9ecef',
  },
  listHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: '12px',
  },
  listTitle: {
    fontSize: '18px',
    fontWeight: '600',
    color: '#2c3e50',
    margin: 0,
  },
  listBadges: {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: '4px',
    alignItems: 'flex-end',
  },
  autoBadge: {
    backgroundColor: '#6f42c1',
    color: '#fff',
    padding: '2px 6px',
    borderRadius: '10px',
    fontSize: '10px',
    fontWeight: '600',
  },
  statusBadge: {
    color: '#fff',
    padding: '4px 8px',
    borderRadius: '12px',
    fontSize: '12px',
    fontWeight: '500',
  },
  listMeta: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px',
    fontSize: '12px',
    color: '#6c757d',
  },
  listDate: {},
  emailSent: {
    color: '#28a745',
  },
  listActions: {
    display: 'flex',
    gap: '8px',
  },
  viewButton: {
    backgroundColor: '#6c757d',
    color: '#fff',
    border: 'none',
    borderRadius: '6px',
    padding: '8px 12px',
    fontSize: '12px',
    cursor: 'pointer',
    flex: 1,
  },
  emailButton: {
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: '6px',
    padding: '8px 12px',
    fontSize: '12px',
    cursor: 'pointer',
    flex: 1,
  },
  modal: {
    position: 'fixed' as const,
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0,0,0,0.5)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000,
  },
  modalContent: {
    backgroundColor: '#fff',
    borderRadius: '12px',
    width: '90%',
    maxWidth: '600px',
    maxHeight: '80vh',
    overflow: 'auto',
  },
  modalHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '20px 24px',
    borderBottom: '1px solid #e9ecef',
  },
  modalTitle: {
    fontSize: '20px',
    fontWeight: '600',
    color: '#2c3e50',
    margin: 0,
  },
  closeButton: {
    backgroundColor: 'transparent',
    border: 'none',
    fontSize: '24px',
    cursor: 'pointer',
    color: '#6c757d',
  },
  modalBody: {
    padding: '24px',
  },
};

export default ShoppingPage;
